mapper.select:
SELECT t1.lms_user_id AS lmsUserId, t1.user_id AS userId, t2.user_name AS userName, t2.kana AS kana, t2.subsidy_category_id AS subsidyCategoryId, t1.role AS role, t2.login_id AS loginId, t1.hope_via_traning AS hopeViaTraning, t1.programming_experience AS programmingExperience, t4.company_name AS companyName, t6.course_id AS courseId, t6.course_name AS courseName, t8.place_name AS placeName, t8.place_note AS placeNote, t8.place_description AS placeDescription, t1.account_id AS accountId, t2.leave_flg AS leaveFlg, t2.leave_date AS leaveDate FROM m_lms_user t1 INNER JOIN m_user t2 ON t1.user_id = t2.user_id LEFT JOIN t_user_company t3 ON t1.lms_user_id = t3.lms_user_id LEFT JOIN m_company t4 ON t3.company_id = t4.company_id LEFT JOIN t_course_user t5 ON t1.lms_user_id = t5.lms_user_id LEFT JOIN m_course t6 ON t5.course_id = t6.course_id LEFT JOIN t_user_place t7 ON t1.lms_user_id = t7.lms_user_id LEFT JOIN m_place t8 ON t7.place_id = t8.place_id WHERE t1.delete_flg = #{deleteFlg} AND t6.course_name LIKE CONCAT('%', #{courseName}, '%') AND t4.company_name LIKE CONCAT('%', #{companyName}, '%') AND t2.user_name LIKE CONCAT('%', #{userName}, '%')
AND t8.place_id IN #{pid}
AND t1.role = #{role} AND t2.leave_flg = 1 AND t6.close_time >= #{closeTime} ORDER BY t1.lms_user_id ASC
